import {notificationsUI} from './notifications.js';
import {identityUI} from './identity.js';
import {optimizationUI} from './optimization.js';
import {workflowUI} from './workflow.js';
import {reportingUI} from './reporting.js';
import {cloudUI} from './cloud.js';
import {instagramUI} from './instagram.js';
import {catalogUI} from './catalog.js';
import {commerceUI} from './commerce.js';
import {operationsUI} from './operations.js';
import {deliveryUI} from './delivery.js';
const $ = s => document.querySelector(s);
const esc = v => String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',campaign:'<path d="M4 8h16v12H4zM8 8V4h8v4M4 12h16M10 12v3h4v-3"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 5"/>',pipeline:'<path d="M3 5h18l-7 8v6l-4 2v-8z"/>',proposal:'<path d="M14 3H5v18h14V8zM14 3v5h5M8 12h8M8 16h6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18M7 14h2M15 14h2M7 17h2"/>',money:'<rect x="2" y="5" width="20" height="15" rx="2"/><path d="M2 10h20M6 15h4"/>',chart:'<path d="M4 3v17h17M8 15l4-5 4 2 5-7"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5M12 17h.01"/>',arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',down:'<path d="m6 9 6 6 6-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',bell:'<path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5zM10 21h4"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',location:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',star:'<path d="m12 3 3 6 6 1-4.5 4.5 1 6.5-5.5-3-5.5 3 1-6.5L3 10l6-1Z"/>',external:'<path d="M14 3h7v7M21 3 11 13M10 3H3v18h18v-7"/>',leaf:'<path d="M4 20C2 8 8 3 21 3c0 13-5 19-17 17ZM4 20 16 8"/>',logout:'<path d="M9 3H4v18h5M9 12h12M16 7l5 5-5 5"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',link:'<path d="m10 7 2-2a5 5 0 0 1 7 7l-3 3M14 17l-2 2a5 5 0 0 1-7-7l3-3M8 16l8-8"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>',inbox:'<path d="m3 15 3-11h12l3 11v6H3ZM3 15h5l2 3h4l2-3h5"/>'};
const icon = n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.grid}</svg>`;
const image=(id)=>`/art/${id}.svg`;
const portraits={c_asha:'asha',c_rohan:'rohan',c_meera:'meera',c_zoya:'zoya',c_arjun:'arjun',c_tara:'tara'};
const covers={b_olive:'olive',b_north:'north',b_form:'form'};
const money=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format((v||0)/100);
const compact=n=>new Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(n);
const date=d=>d?new Date(d.length===10?d+'T12:00:00Z':d).toLocaleDateString('en-IN',{day:'numeric',month:'short',timeZone:'Asia/Kolkata'}):'Not set';
const dateLong=()=>new Date().toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Kolkata'});
const tag=(t,c='')=>`<span class="tag ${c}">${esc(t)}</span>`;
const btn=(label,action,cl='',ic='')=>`<button class="btn ${cl}" data-action="${esc(action)}">${ic?icon(ic):''}${esc(label)}</button>`;
const empty=(title,desc,action='')=>`<div class="empty">${icon('leaf')}<h3>${esc(title)}</h3><p>${esc(desc)}</p>${action}</div>`;
let calendarOffset=0;
let state=null,publicData=null,view='overview',filter='All',search='',selectedBrand='b_olive',previousFocus=null;
async function api(path,body){const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok)throw Object.assign(new Error(data.error||'Request failed.'),{status:r.status});return data;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function openModal(title,html,wide=false){previousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></header><div class="modal-body">${html}</div></section></div>`;document.body.classList.add('modal-open');setTimeout(()=>$('.modal input:not([type=hidden]),.modal select,.modal button')?.focus(),30);}
function closeModal(){$('#modal-root').innerHTML='';document.body.classList.remove('modal-open');previousFocus?.focus();}
function logo(){return '<a data-action="public" class="logo" href="#" aria-label="Voqro home"><span class="logo-mark">✳</span>voqro<span class="logo-period">.</span></a>';}
function metricSource(c){return `${esc(c.metric_source||'Source not supplied')} · ${esc(c.observed_on||'Date not supplied')}<br>Sample: ${esc(c.sample_size==null?'unknown':c.sample_size+' posts')} · ${esc(c.sample_kind||'Type unknown')}`;}
function publicServices(){return (publicData.content||[]).filter(c=>c.kind==='Service').map(c=>`<article class="service-card">${icon('leaf')}<h3>${esc(c.title)}</h3><p>${esc(c.summary)}</p>${btn('Explore service','public-content:'+c.id,'subtle','arrow')}</article>`).join('');}
function publicCaseStudies(){const cases=(publicData.content||[]).filter(c=>c.kind==='Case study');return cases.length?`<section class="public-section"><div class="section-heading"><h2>Stories from the work.</h2></div><div class="services-grid">${cases.map(c=>`<article class="service-card"><h3>${esc(c.title)}</h3><p>${esc(c.summary)}</p>${btn('Read case study','public-content:'+c.id,'subtle','arrow')}</article>`).join('')}</div></section>`:'';}
function creatorCard(c,publicView=false){const saved=state?.shortlists.some(s=>s.creator_id===c.id&&s.brand_id===(state.user.brand_id||selectedBrand));return `<article class="creator-card"><div class="creator-portrait"><img src="${image(portraits[c.id]||'profile')}" alt="Profile illustration for ${esc(c.name)}" loading="lazy">${tag(c.niche)}${!publicView&&canShortlist()?`<button data-action="shortlist:${c.id}" aria-label="${saved?'Remove '+esc(c.name)+' from':'Add '+esc(c.name)+' to'} shortlist">${icon(saved?'check':'plus')}</button>`:''}</div><div class="creator-body"><h3>${esc(c.name)}</h3><p class="handle">@${esc(c.handle)}</p><div class="creator-metrics"><div><strong>${c.followers==null?'Unknown':compact(c.followers)}</strong><small>Followers</small></div><div><strong>${c.engagement==null?'Unknown':c.engagement+'%'}</strong><small>Engagement</small></div></div><div class="creator-location">${icon('location')}${esc(c.location)} · ${esc(c.language.split(',')[0])}</div><div class="source-note">${metricSource(c)}</div><button class="btn subtle" data-action="creator:${c.id}">Meet ${esc(c.name.split(' ')[0])} ${icon('arrow')}</button></div></article>`;}
function publicPage(){const p=publicData;$('#app').innerHTML=`<header class="public-header">${logo()}<nav class="public-nav" aria-label="Public navigation"><a href="#creators">Our creators</a><a href="#services">What we do</a>${btn('Let’s work together','enquire','','arrow')}${btn('Workspace','login','primary')}</nav></header><main><section class="public-hero"><div><div class="eyebrow">Independent minds. Collective impact.</div><h1>Good people.<br>Great stories.<br><em>Real connection.</em></h1><p>We bring thoughtful brands and original creators together. From the first spark to the final story, we make good work happen.</p><div class="hero-actions"><a href="#creators" class="btn primary">Find your people ${icon('arrow')}</a>${btn('Meet your agency','about')}</div><div class="public-proof">${icon('leaf')}A little more human. A lot more meaningful.</div></div><div class="public-visual"><img src="${image('together')}" alt="A creative team sharing ideas around a table"></div></section><section class="public-section" id="creators"><div class="section-heading"><div><div class="eyebrow">The people behind the stories</div><h2>Original voices. Real influence.</h2></div>${tag(p.demo?'Demonstration catalogue':'Approved creator profiles','gray')}</div><div class="creator-grid">${p.creators.map(c=>creatorCard(c,true)).join('')||empty('The collective is taking shape.','Approved creator profiles will appear here.')}</div></section><section class="public-section" id="services"><div class="section-heading"><div><div class="eyebrow">From idea to impact</div><h2>Your story, in good hands.</h2></div></div><div class="services-grid">${publicServices()}${(p.content||[]).some(c=>c.kind==='Service')?'':`<article class="service-card"><div class="eyebrow">01 / Creator partnerships</div>${icon('users')}<h3>The right kind of chemistry.</h3><p>Find creators who share your values, speak to your audience, and bring a perspective all their own.</p></article><article class="service-card"><div class="eyebrow">02 / Campaign strategy</div>${icon('leaf')}<h3>Thoughtful from the start.</h3><p>A clear brief, a considered plan, and a creative direction that makes every collaboration feel like you.</p></article><article class="service-card"><div class="eyebrow">03 / End-to-end management</div>${icon('campaign')}<h3>All the moving parts. Handled.</h3><p>One team for your partnerships, production and reporting. More room for you to focus on what comes next.</p></article>`}</div></section>${publicCaseStudies()}<section class="public-section"><div class="public-cta"><div><h2>Something good starts here.</h2><p>Tell us what you’re imagining. We’ll help you bring it to life.</p></div>${btn('Let’s make it happen','enquire','lime','arrow')}</div>${p.demo?`<div class="notice">${icon('help')}This is a working demonstration. Creator identities, illustrations, brands and campaign records are illustrative; no commercial results are claimed.</div>`:''}</section></main><footer class="public-footer"><span>© ${new Date().getFullYear()} Voqro. Made for meaningful work.</span><button data-action="login">Open your workspace ↗</button></footer>`;}
const canSales=()=>state&&['owner','manager'].includes(state.user.role);
const canShortlist=()=>state&&['owner','manager','brand'].includes(state.user.role);
const brand=id=>state.brands.find(b=>b.id===id);
const creator=id=>state.creators.find(c=>c.id===id);
const campaignAssignments=id=>state.assignments.filter(a=>a.campaign_id===id);
const campaignDeliverables=id=>state.deliverables.filter(d=>campaignAssignments(id).some(a=>a.id===d.assignment_id));
function navGroups(){const role=state.user.role;return [
 {label:'Workspace',items:[['overview','grid','Overview'],['campaigns','campaign','Campaigns'],...(role==='creator'?[]:[['creators','users','Creators']]),['calendar','calendar','Calendar'],['workflow','proposal','Tasks & knowledge']]},
 {label:'Sales & audience',items:[...(canSales()?[['pipeline','pipeline','Enquiry pipeline'],['optimization','users','Matching & experiments']]:[]),...(role==='creator'?[]:[['proposals','proposal','Proposals']])]},
 {label:'Delivery & results',items:[...(role==='finance'?[]:[['operations','settings','Operations'],['cloud','chart','Media & AI'],['instagram','link','Instagram'],['results','chart','Results']]),...(['owner','manager','reviewer'].includes(role)?[['trends','leaf','Trend evidence']]:[]),['reporting','chart','Reports']]},
 {label:'Agency management',items:[...(['owner','finance','brand','creator'].includes(role)?[['finance','money',role==='brand'?'Invoices':role==='creator'?'Payouts':'Finance']]:[]),...(canSales()?[['catalog','users','Catalogue & website']]:[]),...(role==='owner'?[['access','users','People & access'],['email-delivery','bell','Email delivery']]:[])]}
 ].filter(group=>group.items.length);}
function navItems(){return navGroups().flatMap(group=>group.items);}
function navigation(){return navGroups().map(group=>`<div class="nav-caption">${esc(group.label)}</div>${group.items.map(([id,i,t])=>`<button class="nav-item ${view===id?'active':''}" data-action="nav:${id}" ${view===id?'aria-current="page"':''}>${icon(i)}${esc(t)}${id==='campaigns'?`<span class="nav-badge">${state.campaigns.length}</span>`:''}</button>`).join('')}`).join('');}

function render(){if(!state){publicPage();return;}const user=state.user;const title=Object.fromEntries(navItems().map(([id,i,t])=>[id,t]))[view]||({connections:'Connections',help:'Help & roadmap',attention:'Needs attention',shortlist:'Your shortlist',knowledge:'Brand knowledge',inbox:'Your inbox',exceptions:'Exceptions'}[view])||'Campaign workspace';$('#app').innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar">${logo()}<div class="workspace-name"><div class="workspace-icon">v.</div><div>Voqro workspace<small>${esc(user.role==='brand'?brand(user.brand_id)?.name:user.role==='creator'?'Creator studio':'Agency workspace')}</small></div></div><nav class="nav-group" aria-label="Workspace">${navigation()}</nav><div class="nav-caption">MANAGE</div><nav class="nav-group" aria-label="Manage"><button class="nav-item ${view==='connections'?'active':''}" data-action="nav:connections">${icon('link')}Connections</button><button class="nav-item ${view==='help'?'active':''}" data-action="nav:help">${icon('help')}Help & roadmap</button></nav><div class="sidebar-bottom"><div class="plan-card">A little space for big ideas.<p>Your agency, all in one place.</p><span class="demo-label">${state.demo?'◌ Demonstration workspace':'◌ Agency workspace'}</span></div><div class="profile"><div class="avatar">${esc(user.name.slice(0,1))}</div><div><strong>${esc(user.name.split(' · ')[0])}</strong><small>${esc(user.role==='owner'?'Agency owner':user.role.charAt(0).toUpperCase()+user.role.slice(1))}</small></div><button class="icon-btn" data-action="account" aria-label="Account options">${icon('down')}</button></div></div></aside><div class="main"><header class="topbar"><div class="breadcrumbs"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><span>Workspace</span><span>/</span><b>${esc(title)}</b></div><div class="top-tools"><button class="search-box" data-action="search" aria-label="Search workspace">${icon('search')}<span>Search anything...</span><span class="key">⌘ K</span></button><button class="icon-btn" data-action="nav:exceptions" aria-label="View items needing attention">${icon('bell')}<span class="notice-dot"></span></button><div class="avatar">${esc(user.name.slice(0,1))}</div></div></header><main class="content">${renderView()}<footer class="bottom-note"><span>Built for good work, together.</span><span>${state.demo?'Demo workspace · Local operations':'Agency workspace · Verified membership'}</span></footer></main></div></div>`;}
function heading(title,desc,action='',eyebrow='YOUR WORKSPACE'){return `<div class="page-title"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>${action}</div>`;}
function stat(label,value,foot,i='chart'){return `<div class="stat"><div class="stat-top">${esc(label)}${icon(i)}</div><div class="stat-number">${esc(value)}</div><div class="stat-foot">${foot}</div></div>`;}
function campaignCard(c){const ds=campaignDeliverables(c.id),as=campaignAssignments(c.id),b=brand(c.brand_id);return `<article class="campaign-card" role="button" tabindex="0" data-action="campaign:${c.id}" aria-label="Open ${esc(c.name)}"><div class="campaign-image"><img src="${image(covers[c.brand_id]||covers.b_olive)}" alt="" loading="lazy">${tag(c.status,c.status==='Planning'?'amber':'')}<span class="campaign-initial">${esc(b?.name)}</span><span class="image-label">Creator stories</span></div><div class="campaign-body"><div class="campaign-brand">${esc(b?.industry)}</div><h3>${esc(c.name)}</h3><p class="campaign-description">${esc(c.description)}</p><div class="progress-row"><span>${ds.length} deliverables</span><span>${ds.filter(d=>d.status==='Published').length} published</span></div><div class="progress-track"><span></span></div><div class="campaign-footer"><div class="avatar-stack">${as.slice(0,4).map(a=>`<div class="avatar" title="${esc(creator(a.creator_id)?.name)}">${esc(creator(a.creator_id)?.initials)}</div>`).join('')}${!as.length?'Creators to be assigned':''}</div><span class="date">${icon('calendar')}${c.end_date?date(c.end_date):'Dates to be confirmed'}</span></div></div></article>`;}
function attentionItems(){return [...state.proposals.filter(p=>p.status==='Sent').map(p=>({title:state.user.role==='brand'?'Your proposal is ready':'Proposal awaiting a decision',desc:`${brand(p.brand_id)?.name} · ${p.title}`,action:'proposal:'+p.id,label:'Review proposal',i:'proposal'})),...state.deliverables.filter(d=>d.status==='Draft due'||d.status==='Brief needed').slice(0,3).map(d=>({title:d.status==='Brief needed'?'A brief needs a starting point':'A creator draft is coming up',desc:`${d.owner} · ${d.due_date?date(d.due_date):'Date to be confirmed'}`,action:'deliverable:'+d.id,label:'View assignment',i:'clock'}))];}
const salesAttention=attentionItems;
attentionItems=function(){const existing=salesAttention();const user=state.user;const review=state.deliverables.filter(d=>user.role==='brand'?d.status==='Brand review':user.role==='creator'?['Changes requested','Brief changed'].includes(d.status):['Agency review','Changes requested','Brief changed'].includes(d.status)).map(d=>({title:d.status==='Agency review'?'A draft is ready for agency review':d.status==='Brand review'?'Your approval is needed':d.status==='Brief changed'?'The brief has changed':'A new version is needed',desc:d.owner+' · '+d.title,action:'deliverable:'+d.id,label:'Open review studio',i:'proposal'}));return [...review,...existing];};
function attentionPanel(){const items=attentionItems();return `<section class="panel"><div class="panel-title"><h2>${icon('clock')}Needs a little attention</h2><span class="counter">${items.length}</span></div>${items.length?items.slice(0,3).map(i=>`<div class="attention-item"><div class="attention-icon">${icon(i.i)}</div><div><h3>${esc(i.title)}</h3><p>${esc(i.desc)}</p><button class="text-link" data-action="${i.action}">${i.label} ↗</button></div></div>`).join(''):'<p class="source-note">A little breathing room. Nothing waiting on you.</p>'}${btn('View all','nav:attention','subtle','arrow')}</section>`;}
function upcomingPanel(){const ds=[...state.deliverables].filter(d=>d.due_date).sort((a,b)=>a.due_date.localeCompare(b.due_date));return `<section class="panel"><div class="panel-title"><h2>On the horizon</h2>${icon('calendar')}</div>${ds.slice(0,3).map(d=>`<button class="mini-event" data-action="deliverable:${d.id}"><span class="date-block"><small>${new Date(d.due_date).toLocaleDateString('en',{month:'short'}).toUpperCase()}</small><strong>${new Date(d.due_date).getUTCDate()}</strong></span><span><h3>${esc(d.title.split(' · ')[0])}</h3><p>${esc(d.owner)}</p><span class="event-meta">${esc(d.status)} · Instagram</span></span></button>`).join('')||'<p class="source-note">No dates assigned yet.</p>'}<button class="btn subtle" data-action="nav:calendar">Open calendar ${icon('arrow')}</button></section>`;}
function overview(){const name=state.user.name.split(' ')[0],role=state.user.role;const active=state.campaigns.filter(c=>c.status==='Active').length;return heading(`Good to see you, ${name}.`,'Here’s what’s happening across your workspace.',canSales()?btn('New proposal','new-proposal','primary','plus'):btn('View assignments','nav:campaigns','','arrow'),dateLong().toUpperCase())+`<section class="greeting-card"><div><div class="eyebrow">A little clarity. A lot of possibility.</div><h2>Great work starts with good company.</h2><p>${role==='brand'?'Your creators, your stories, and your next big idea. Let’s bring it all together.':role==='creator'?'Your ideas make the difference. Find your next brief and keep the good work moving.':'Your campaigns are moving. Your people are creating. Here’s the space to keep it all coming together.'}</p>${btn('Explore your campaigns','nav:campaigns','','arrow')}</div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><div class="hero-sticker"><span>✳</span></div><span class="art-spark">✧</span><span class="art-spark last">✧</span><span class="hero-note">Made for meaningful work ↗</span></div></section><div class="stats">${stat('Active campaigns',String(active).padStart(2,'0'),'<b>↗</b> '+state.campaigns.length+' campaigns in your workspace','campaign')}${stat(role==='creator'?'Your assignments':'Creator partnerships',String(state.assignments.length).padStart(2,'0'),'<b>◌</b> '+new Set(state.assignments.map(a=>a.creator_id)).size+' original voices','users')}${stat('Deliverables',String(state.deliverables.length).padStart(2,'0'),'<b>↗</b> Stories in the making','proposal')}${stat(role==='creator'?'Upcoming deadlines':'Open proposals',String(role==='creator'?state.deliverables.filter(d=>d.due_date).length:state.proposals.filter(p=>p.status==='Sent').length).padStart(2,'0'),role==='creator'?'Dates from your assignments':'Waiting for a brand decision','clock')}</div><div class="dashboard-grid"><div><div class="section-heading"><h2>Your campaigns</h2>${btn('View all campaigns','nav:campaigns','subtle','arrow')}</div><div class="tabs" role="tablist"><button class="tab ${filter==='All'?'active':''}" data-action="overview-filter:All" role="tab" aria-selected="${filter==='All'}">All campaigns<span class="tab-count">${state.campaigns.length}</span></button><button class="tab ${filter==='Active'?'active':''}" data-action="overview-filter:Active" role="tab" aria-selected="${filter==='Active'}">Active</button><button class="tab ${filter==='Planning'?'active':''}" data-action="overview-filter:Planning" role="tab" aria-selected="${filter==='Planning'}">Planning</button></div><div class="campaign-grid">${state.campaigns.filter(c=>filter==='All'||c.status===filter).slice(0,4).map(campaignCard).join('')||empty('Room for something good','Campaigns appear here when a brand accepts a proposal.')}</div><section class="activity-panel"><div class="section-heading"><h2>Around the workspace</h2><span class="demo-label">Recent activity</span></div><div class="activity-list">${state.activities.slice(0,3).map(a=>`<div class="activity-row"><div class="avatar">${esc(a.actor[0])}</div><p><strong>${esc(a.actor)}</strong> · ${esc(a.message)}</p><small>${date(a.created)}</small></div>`).join('')||'<p class="source-note">Your next chapter starts with a brief.</p>'}</div></section></div><aside class="right-stack">${attentionPanel()}${upcomingPanel()}</aside></div>`;}
function creatorsPage(shortlist=false){let cs=state.creators.filter(c=>(filter==='All'||c.niche===filter)&&(c.name+' '+c.niche+' '+c.location+' '+c.language).toLowerCase().includes(search.toLowerCase()));if(shortlist)cs=cs.filter(c=>state.shortlists.some(s=>s.creator_id===c.id&&s.brand_id===(state.user.brand_id||selectedBrand)));return heading(shortlist?'Your kind of people.':'Original voices. Shared possibilities.',shortlist?'A considered collection for your next campaign.':'Find the people who make your brand feel a little more human.',canShortlist()?btn(shortlist?'All creators':'View shortlist',shortlist?'nav:creators':'nav:shortlist','','users'):'','THE CREATOR COLLECTIVE')+`<div class="toolbar"><div class="field-search">${icon('search')}<input id="creator-search" placeholder="Search name, city, language…" aria-label="Search creators" value="${esc(search)}"></div>${['All','Lifestyle','Travel','Design','Food','Fitness'].map(f=>`<button class="filter-pill ${filter===f?'active':''}" data-action="filter:${f}">${f}</button>`).join('')}${canSales()?`<select class="version-select" id="shortlist-brand" aria-label="Brand for shortlist">${state.brands.map(b=>`<option value="${esc(b.id)}" ${b.id===selectedBrand?'selected':''}>${esc(b.name)}</option>`).join('')}</select>`:''}</div><div class="creator-grid" id="creator-grid">${cs.map(c=>creatorCard(c)).join('')||empty('No creators here yet',shortlist?'Add people from the creator catalogue to build your shortlist.':'Try another niche, city or name.')}</div><p class="fineprint">Catalogue figures show their evidence source and sample. Manually supplied statistics are unverified. Engagement is not a prediction of campaign results.</p>`;}
function pipeline(){const stages=['Enquiry','Qualified','Discovery','Proposal','Negotiation','Won','Lost'];return heading('From a hello to something good.','Every relationship starts somewhere. Keep the next step clear.',btn('Add enquiry','enquire','primary','plus'),'ENQUIRY PIPELINE')+`<div class="stats">${stat('Open conversations',state.leads.filter(l=>!['Won','Lost'].includes(l.stage)).length,'A little potential in every brief','pipeline')}${stat('Pipeline value',money(state.leads.filter(l=>!['Won','Lost'].includes(l.stage)).reduce((s,l)=>s+l.budget,0)),'Indicative budgets · not revenue','money')}${stat('Proposals shared',state.proposals.length,'Versioned, with clear terms','proposal')}${stat('Won enquiries',state.leads.filter(l=>l.stage==='Won').length,'Accepted by the brand','check')}</div><div class="kanban">${stages.map(s=>`<section class="kanban-col"><div class="kanban-title">${s}<span class="tag gray">${state.leads.filter(l=>l.stage===s).length}</span></div>${state.leads.filter(l=>l.stage===s).map(l=>`<button class="lead-card" data-action="lead:${l.id}"><h3>${esc(l.company)}</h3><p>${esc(l.brief.slice(0,90))}</p><strong>${money(l.budget)}</strong><footer>${esc(l.owner)}<br>${l.follow_up?'Follow up '+date(l.follow_up):'Follow-up date to be assigned'}</footer></button>`).join('')}</section>`).join('')}</div>`;}
function proposalsPage(){return heading('Make the possibilities tangible.','Clear scope. Thoughtful partnerships. Every version, in one place.',canSales()?btn('New proposal','new-proposal','primary','plus'):'','PROPOSALS & PACKAGES')+state.proposals.map(p=>{const v=p.versions[0];return `<article class="proposal-card"><div><div class="badge-row">${tag(p.status,p.status==='Sent'?'amber':'')}${tag('Version '+v.version,'gray')}</div><h3>${esc(p.title)}</h3><p>${esc(brand(p.brand_id)?.name)} · ${v.payload.items.length} line items · Valid until ${date(v.payload.expires)}</p></div><div class="proposal-actions"><div class="proposal-price">${money(v.total)}</div>${btn('View proposal','proposal:'+p.id,'','arrow')}</div></article>`;}).join('')+(state.proposals.length?'':empty('A good partnership starts with a clear plan.','Proposals shared with you will appear here.'));}
function campaignPage(id){return delivery.campaignPage(id);}
function calendar(){const current=new Date(),target=new Date(current.getFullYear(),current.getMonth()+calendarOffset,1),month=target.getMonth(),year=target.getFullYear(),first=target.getDay(),days=new Date(year,month+1,0).getDate(),cells=Math.ceil((first+days)/7)*7;return heading('Make room for what’s next.','Assignment due dates, together in one view.','','YOUR CALENDAR')+`<div class="section-heading"><h2>${target.toLocaleDateString('en-IN',{month:'long',year:'numeric'})}</h2><div class="badge-row"><button class="icon-btn" data-action="calendar-prev" aria-label="Previous month">${icon('back')}</button><button class="icon-btn" data-action="calendar-next" aria-label="Next month">${icon('arrow')}</button></div></div><div class="notice">${icon('calendar')}Assignment deadlines only. Instagram scheduling is not connected.</div><div class="calendar-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="calendar-heading">${d}</div>`).join('')}${Array.from({length:cells},(_,i)=>{const n=i-first+1,valid=n>0&&n<=days;return `<div class="calendar-day ${valid?'':'blank'}">${valid?n:''}${valid?state.deliverables.filter(d=>d.due_date===`${year}-${String(month+1).padStart(2,'0')}-${String(n).padStart(2,'0')}`).map(d=>`<button class="calendar-event" data-action="deliverable:${d.id}">${esc(d.title)}<br>${esc(d.owner)}</button>`).join(''):''}</div>`;}).join('')}</div>`;}
function finance(){return cash.render();}
function connections(){const c=state.connections||{},role=state.user.role;const cards=[
 ['users','Identity & sign-in',c.identity?.status||'Not configured',c.identity?.available?'Configured; live verification required':state.demo?'Demo only':'Not configured',role==='owner'?'access':null],
 ['link','Instagram',c.instagram?.message||'Meta authorisation is not configured.',c.instagram?.connected_accounts?c.instagram.connected_accounts+' authorised accounts':'No authorised accounts',role!=='finance'?'instagram':null],
 ['chart','Media & AI',(c.cloud?.local_evidence||'Local technical checks available')+'. '+(c.cloud?.ai||'AI not configured'),c.cloud?.ai||'Not configured',role!=='finance'?'cloud':null],
 ['grid','Storage & recovery','Local database and completed media can be exported, verified and restored. '+(c.cloud?.storage||'AWS storage not configured'),c.cloud?.verified_at?'Last provider verification '+date(c.cloud.verified_at):'Local storage; cloud unverified',role!=='finance'?'cloud':null],
 ['money','Payments & agreements','Invoices, payment milestones, settlement records and agreement acknowledgements are available. '+(c.signing||''),c.payments||'No payment provider','reporting'],
 ['bell','Notifications','In-app reminders are available. Email: '+(c.notifications?.email||'Not configured')+'. External reminders require explicit owner queuing and verified recipients.',c.notifications?.in_app||'Available',role==='owner'?'email-delivery':'inbox']
 ];return heading('Good connections make good work.','Configuration, recorded authorisation and live verification are shown separately.','','INTEGRATIONS')+`<div class="integration-grid">${cards.map(([i,t,d,status,target])=>`<section class="integration-card">${icon(i)}<h3>${esc(t)}</h3><p>${esc(d)}</p>${tag(status,'gray')}${target?`<div class="detail-tags">${btn('Open workspace','nav:'+target,'subtle','arrow')}</div>`:''}</section>`).join('')}</div>`;}

function help(){return heading('Built one complete workflow at a time.','Application features are available to exercise. External release evidence remains separate.','','HELP & RELEASE STATUS')+`<div class="table-wrap"><table><thead><tr><th>Release</th><th>Implemented workflow</th><th>Remaining completion evidence</th></tr></thead><tbody>${[
 ['01 · Foundation & sales','Catalogue, lead pipeline, accepted proposals, scoped memberships and Cognito sign-in adapter','Real external-owner and brand onboarding with the configured provider'],
 ['02 · Campaign delivery','Versioned briefs, uploads, knowledge, tasks, review, rights and dispatch','Live private-storage access, safety checks and operational recovery drill'],
 ['03 · AI & Instagram','Bounded evidence jobs, provider adapters, account authorisation, publishing reconciliation and insights','A supported approved post published and independently verified through Meta'],
 ['04 · Commercial operations','Invoices, milestones, costs, settlement corrections, agreement records and shared reports','A real paid campaign reconciled against payment evidence; provider signing and payment execution remain separate'],
 ['05 · Optimisation','Explainable matching, reliability evidence, forecasting and registered experiments','Measured recommendations outperform an agreed baseline; no outcome is assumed']
 ].map(([r,scope,evidence])=>`<tr><td>${esc(r)}</td><td>${esc(scope)}</td><td>${esc(evidence)}</td></tr>`).join('')}</tbody></table></div><section class="activity-panel"><h2>Try a complete campaign</h2><p class="terms">Enquiry → proposal → acceptance → brief and tasks → upload → revision and approvals → handoff or provider publishing → report and reconcile. Match creators and register a baseline experiment before measuring results.</p><p class="terms">Configuration alone does not establish provider access, a verified live post or improved outcomes. The app retains source labels, missing data and the exact version behind each decision.</p>${state.demo?btn('Switch demo workspace','login','','users'):''}${btn('Visit agency website','public','','external')}</section>`;}

function renderView(){if(view==='email-delivery')return emailPanel.render();if(view==='optimization')return opt.render();if(['workflow','knowledge','inbox','exceptions'].includes(view))return wf.render(view);if(view==='reporting')return reports.render();if(view==='cloud')return cloudPanel.render();if(view==='instagram')return ig.render();if(view==='access')return accessPanel.render();if(['operations','trends','results'].includes(view))return ops.render(view);if(view==='overview')return overview();if(view==='creators'||view==='shortlist')return creatorsPage(view==='shortlist');if(view==='pipeline')return pipeline();if(view==='proposals')return proposalsPage();if(view==='calendar')return calendar();if(view==='catalog')return cat.render();if(view==='finance')return finance();if(view==='connections')return connections();if(view==='help')return help();if(view==='attention')return heading('A little attention goes a long way.','The next decisions and assignments, in one place.','','EXCEPTIONS & NEXT ACTIONS')+attentionPanel();if(view.startsWith('campaign:'))return campaignPage(view.split(':')[1]);return heading('Good stories, in the making.','Your campaigns and the people bringing them to life.',canSales()?btn('Create from proposal','nav:proposals','primary','plus'):'','CAMPAIGNS')+`<div class="campaign-grid">${state.campaigns.map(campaignCard).join('')}</div>`;}
function loginModal(){if(!publicData.demo){openModal(publicData.identity?.available?'Welcome to your workspace.':'Sign-in isn’t configured',`<p class="modal-description">${esc(publicData.identity?.available?'Continue through your agency’s identity provider. Your verified membership determines the workspace you can access.':publicData.identity?.status||'Production identity is not configured.')}</p><div class="modal-footer">${accessPanel.signInButton(publicData.identity)}${btn('Close','close')}</div>`);return;}openModal('Find your workspace.',`<p class="modal-description">Explore the product from a different perspective. These shared demo accounts contain illustrative data and do not represent secure production sign-in.</p><div class="demo-options">${[['u_owner','Agency owner','Abhinav · campaigns, sales and finances','grid'],['u_manager','Account manager','Naina · sales and campaign management','campaign'],['u_brand','Brand · Olive & Earth','Priya · your proposals, creators and campaigns','leaf'],['u_other','Brand · Northstar','Alex · a separate brand workspace','leaf'],['u_creator','Creator · Asha Mehta','Your assignments and campaign briefs','users'],['u_finance','Finance team','Sam · invoices, costs and reconciliation','money'],['u_reviewer','Reviewer','Dev · campaign visibility, no sales editing','proposal']].map(([id,title,desc,i])=>`<button class="demo-option" data-action="sign-in:${id}"><span class="avatar">${icon(i)}</span><span><strong>${title}</strong><small>${desc}</small></span>${icon('arrow')}</button>`).join('')}</div><div class="fineprint">Demo sessions expire after 24 hours. Finance controls are restricted to owner and finance accounts. Brands see their invoices; creators see their own payout records.</div>`);}
function enquiryModal(){openModal('Let’s make something good.',`<p class="modal-description">A little about you, a little about your idea. We’ll keep the conversation moving from there.</p><form id="enquiry-form"><div class="form-error" role="alert"></div><div class="form-grid"><div class="form-field"><label for="en-name">Your name</label><input id="en-name" name="name" required maxlength="120" placeholder="Priya Shah" autocomplete="name"></div><div class="form-field"><label for="en-email">Email address</label><input id="en-email" name="email" type="email" required maxlength="200" placeholder="you@brand.com" autocomplete="email"></div><div class="form-field"><label for="en-company">Brand / company</label><input id="en-company" name="company" required maxlength="160" placeholder="Your brand" autocomplete="organization"></div><div class="form-field"><label for="en-budget">Indicative budget (₹)</label><input id="en-budget" name="budget" type="number" min="1" max="100000000" step="0.01" required placeholder="250000"></div><div class="form-field full"><label for="en-brief">What are you imagining?</label><textarea id="en-brief" name="brief" required maxlength="5000" placeholder="Your goals, the kind of creators you love, and when you’d like to get started…"></textarea></div></div><p class="fineprint">This enquiry is stored in the local workspace. Automated email is not connected.</p><div class="modal-footer">${btn('Maybe later','close')}<button class="btn primary" type="submit">Send your brief ${icon('arrow')}</button></div></form>`);}
function creatorModal(id){const c=(state?.creators||publicData.creators).find(c=>c.id===id);if(!c)return;openModal('A voice worth getting to know.',`<div class="profile-hero"><img src="${image(portraits[id]||'profile')}" alt="Profile illustration for ${esc(c.name)}"><div><h2>${esc(c.name)}</h2><p class="source-note">@${esc(c.handle)} · ${esc(c.location)}</p>${tag(c.available?'Open to partnerships':'Currently unavailable',c.available?'':'amber')}</div></div><p class="creator-bio">“${esc(c.bio)}”</p><div class="profile-stat-grid">${stat('Followers',c.followers==null?'Unknown':compact(c.followers),esc(c.metric_source||'Not supplied'),'users')}${stat('Engagement',c.engagement==null?'Unknown':c.engagement+'%',esc(c.sample_size?c.sample_size+' posts':'Sample not supplied'),'chart')}${stat('Languages',c.language.split(',').length,c.language,'users')}</div><div class="notice">${icon('help')}${metricSource(c)}. Metrics are not independently verified. ${c.metric_source==='Demonstration'?'This identity and its illustration are fictional.':'Profile artwork is illustrative.'}</div><div class="modal-footer">${canShortlist()?btn('Update shortlist','shortlist:'+id,'primary','plus'):btn('Enquire about '+c.name.split(' ')[0],'enquire','primary','arrow')}</div>`);}
function leadModal(id){const l=state.leads.find(l=>l.id===id);openModal(l.company,`<div class="badge-row">${tag(l.stage)}${tag(l.source,'gray')}</div><p class="terms">${esc(l.brief)}</p><dl class="detail-meta"><div><dt>Contact</dt><dd>${esc(l.name)} · ${esc(l.email)}</dd></div><div><dt>Indicative budget</dt><dd>${money(l.budget)}</dd></div><div><dt>Owner / follow-up</dt><dd>${esc(l.owner)} · ${date(l.follow_up)}</dd></div></dl><form id="lead-form" data-id="${id}"><div class="form-error" role="alert"></div><div class="form-field detail-tags"><label for="lead-stage">Move conversation to</label><select name="stage" id="lead-stage">${['Enquiry','Qualified','Discovery','Negotiation','Lost'].map(s=>`<option ${l.stage===s?'selected':''}>${s}</option>`).join('')}</select><small>Proposal and Won stages are set by proposal sharing and acceptance.</small></div><div class="modal-footer"><button type="submit" class="btn">Update stage</button>${btn('Build proposal','proposal-lead:'+id,'primary','plus')}</div></form>`);}
let composerItems=[];
function lineItemHTML(item,index){return `<div class="line-item" data-index="${index}"><div><label for="line-label-${index}">Deliverable / service</label><input id="line-label-${index}" name="label" value="${esc(item.label)}" required maxlength="200"><input type="hidden" name="creator_id" value="${esc(item.creator_id||'')}"></div><div><label for="line-quantity-${index}">Qty</label><input id="line-quantity-${index}" name="quantity" type="number" min="1" max="100" value="${item.quantity}" required></div><div><label for="line-price-${index}">Rate (₹)</label><input id="line-price-${index}" name="unit_price" type="number" min="0.01" step="0.01" value="${item.unit_price/100}" required></div><button class="icon-btn" type="button" data-action="remove-line:${index}" aria-label="Remove line item">${icon('close')}</button></div>`;}
function composer(leadId=null,proposalId=null){const p=state.proposals.find(p=>p.id===proposalId),v=p?.versions[0],lead=state.leads.find(l=>l.id===leadId);composerItems=v?v.payload.items.map(i=>({...i})):[{label:'Instagram Reel',quantity:1,unit_price:2500000,creator_id:null}];const expiry=new Date(Date.now()+30*86400000).toISOString().slice(0,10);openModal(p?'A fresh version. A clearer plan.':'A good partnership starts here.',`<form id="proposal-form"><div class="form-error" role="alert"></div><input type="hidden" name="lead_id" value="${esc(leadId||p?.lead_id||'')}"><input type="hidden" name="proposal_id" value="${esc(proposalId||'')}"><div class="form-grid"><div class="form-field full"><label for="proposal-title">Proposal title</label><input id="proposal-title" name="title" required maxlength="180" value="${esc(p?.title||(lead?lead.company+' · Creator partnership':''))}" placeholder="A story worth telling"></div><div class="form-field"><label for="proposal-brand">Brand</label><select id="proposal-brand" name="brand_id" ${lead&&!lead.brand_id?'disabled':''}>${lead&&!lead.brand_id?'<option value="">'+esc(lead.company)+' (new brand)</option>':state.brands.map(b=>`<option value="${esc(b.id)}" ${b.id===(p?.brand_id||lead?.brand_id||selectedBrand)?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div><div class="form-field"><label for="proposal-expiry">Valid until</label><input id="proposal-expiry" name="expires" type="date" min="${new Date().toISOString().slice(0,10)}" value="${expiry}" required></div></div><div class="section-heading"><h3>What we’ll make together</h3><select id="add-creator" class="version-select" aria-label="Add creator line item"><option value="">+ Add a creator</option>${state.creators.filter(c=>c.available).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div id="line-items">${composerItems.map(lineItemHTML).join('')}</div><button class="btn subtle" type="button" data-action="add-line">${icon('plus')}Add service line</button><div class="line-total"><span>Proposal total · INR</span><strong id="proposal-total">${money(composerItems.reduce((s,i)=>s+i.quantity*i.unit_price,0))}</strong></div><div class="form-field"><label for="proposal-terms">Payment terms & revisions</label><textarea name="terms" id="proposal-terms" required maxlength="2000">${esc(v?.payload.terms||'50% deposit, balance within 15 days of delivery. Two revision rounds included.')}</textarea></div><div class="form-field"><label for="proposal-rights">Usage rights & exclusions</label><textarea name="rights" id="proposal-rights" required maxlength="2000">${esc(v?.payload.rights||'Organic Instagram use in India for 90 days. Paid usage and exclusivity excluded.')}</textarea></div><p class="fineprint">Sharing saves an immutable version. Brand acceptance applies only to the latest version and creates the campaign and creator deliverables. No email will be sent.</p><div class="modal-footer">${btn('Cancel','close')}<button class="btn primary" type="submit">Share ${p?'new version':'proposal'} ${icon('arrow')}</button></div></form>`,true);}
function readItems(){return [...document.querySelectorAll('.line-item')].map(el=>({label:el.querySelector('[name=label]').value,quantity:Number(el.querySelector('[name=quantity]').value),unit_price:Math.round(Number(el.querySelector('[name=unit_price]').value)*100),creator_id:el.querySelector('[name=creator_id]').value||null}));}
function updateItems(){composerItems=readItems();$('#proposal-total').textContent=money(composerItems.reduce((s,i)=>s+i.quantity*i.unit_price,0));}
function proposalModal(id,versionId=null){const p=state.proposals.find(p=>p.id===id);if(!p)return;const v=p.versions.find(v=>v.id===versionId)||p.versions[0],latest=v.id===p.versions[0].id;openModal('A plan for something good.',`<div class="section-heading"><div class="badge-row">${tag(p.status,p.status==='Sent'?'amber':'')}${tag(brand(p.brand_id)?.name,'gray')}</div><select id="proposal-version" class="version-select" data-id="${id}" aria-label="Proposal version">${p.versions.map(pv=>`<option value="${pv.id}" ${v.id===pv.id?'selected':''}>Version ${pv.version}${pv.id===p.versions[0].id?' · latest':''}</option>`).join('')}</select></div><h2>${esc(v.payload.title||p.title)}</h2><p class="source-note">Created ${date(v.created)} · Valid until ${date(v.payload.expires)}</p><div class="table-wrap detail-tags"><table><thead><tr><th>Deliverable / service</th><th>Qty</th><th>Rate</th><th>Amount</th></tr></thead><tbody>${v.payload.items.map(i=>`<tr><td>${esc(i.label)}</td><td>${i.quantity}</td><td>${money(i.unit_price)}</td><td>${money(i.quantity*i.unit_price)}</td></tr>`).join('')}</tbody></table></div><div class="line-total"><span>Total · INR</span><strong>${money(v.total)}</strong></div><h3>Payment terms & revisions</h3><p class="terms">${esc(v.payload.terms)}</p><h3>Usage rights</h3><p class="terms">${esc(v.payload.rights)}</p>${state.user.role==='brand'&&p.status!=='Accepted'&&latest?`<form id="accept-form" data-id="${id}" data-version="${v.id}"><div class="form-error" role="alert"></div><label class="check-line"><input type="checkbox" required>I agree to this version’s scope, price, payment terms and usage rights. This demo acceptance creates local records and does not collect payment.</label><div class="modal-footer">${btn('Back to workspace','close')}<button type="submit" class="btn primary">Accept version ${v.version} ${icon('check')}</button></div></form>`:`<div class="modal-footer">${canSales()&&p.status!=='Accepted'?btn('Create a revision','revise:'+id,'','proposal'):''}${p.status==='Accepted'?btn('View campaign','accepted-campaign:'+id,'primary','arrow'):btn('Close','close')}</div>`}${!latest?'<p class="fineprint alert-text">Historical version. Only the latest version can be accepted.</p>':''}`,true);}
function deliverableModal(id){return delivery.action('deliverable:'+id);}
function invalidateModules(){for(const module of [cash,ops,cat,opt,wf,reports,cloudPanel,ig,accessPanel,emailPanel])module.invalidate?.();}
async function refresh(){state=await api('workspace');render();}
async function action(a,el){if(await emailPanel.action(a))return;if(await accessPanel.action(a))return;if(await opt.action(a))return;if(await wf.action(a))return;if(await reports.action(a))return;if(await cloudPanel.action(a))return;if(await ig.action(a))return;if(await cat.action(a))return;if(await cash.action(a,el))return;if(await ops.action(a))return;if(await delivery.action(a))return;const [name,...parts]=a.split(':'),value=parts.join(':');
 if(name==='close')return closeModal();if(name==='login')return loginModal();if(name==='enquire')return enquiryModal();if(name==='creator')return creatorModal(value);
 if(name==='sign-in'){try{invalidateModules();await api('login',{user_id:value});state=await api('workspace');view='overview';filter='All';closeModal();location.hash='workspace';render();toast('Welcome. Your workspace is ready.');}catch(e){toast(e.message);}return;}
 if(name==='public'){closeModal();invalidateModules();state=null;location.hash='';publicData=await api('public');return publicPage();}
 if(name==='nav'){closeModal();view=value;invalidateModules();if(value==='connections')state=await api('workspace');filter='All';search='';render();window.scrollTo(0,0);return;}
 if(name==='calendar-prev'||name==='calendar-next'){calendarOffset+=name==='calendar-next'?1:-1;return render();}
 if(name==='menu'){return $('#sidebar').classList.toggle('open');}
 if(name==='overview-filter'||name==='filter'){filter=value;return render();}
 if(name==='campaign'){closeModal();view='campaign:'+value;render();window.scrollTo(0,0);return;}
 if(name==='lead')return leadModal(value);if(name==='proposal')return proposalModal(value);if(name==='deliverable')return deliverableModal(value);
 if(name==='new-proposal')return composer();if(name==='proposal-lead')return composer(value);if(name==='revise')return composer(null,value);
 if(name==='shortlist'){try{const brandId=state.user.brand_id||selectedBrand;const saved=state.shortlists.some(s=>s.brand_id===brandId&&s.creator_id===value);await api('shortlist',{brand_id:brandId,creator_id:value,remove:saved});await refresh();toast(saved?'Removed from your shortlist.':'A good addition. Creator shortlisted.');}catch(e){toast(e.message);}return;}
 if(name==='add-line'){updateItems();composerItems.push({label:'Campaign management',quantity:1,unit_price:1000000,creator_id:null});$('#line-items').innerHTML=composerItems.map(lineItemHTML).join('');updateItems();return;}
 if(name==='remove-line'){updateItems();composerItems.splice(Number(value),1);$('#line-items').innerHTML=composerItems.map(lineItemHTML).join('');updateItems();return;}
 if(name==='accepted-campaign'){const c=state.campaigns.find(c=>c.proposal_id===value);if(c)return action('campaign:'+c.id);}
 if(name==='account')return openModal('Your corner of Voqro.',`<p class="modal-description">Signed in as ${esc(state.user.name)} · ${esc(state.user.role)}.</p><div class="demo-options">${state.demo?`<button class="demo-option" data-action="login">${icon('users')}Switch demo workspace ${icon('arrow')}</button>`:''}<button class="demo-option" data-action="public">${icon('external')}Visit agency website ${icon('arrow')}</button><button class="demo-option" data-action="logout">${icon('logout')}Sign out ${icon('arrow')}</button></div>`);
 if(name==='logout'){await api('logout',{});closeModal();invalidateModules();state=null;location.hash='';publicPage();return toast('You’re signed out.');}
 if(name==='public-content'){const c=(publicData.content||[]).find(c=>c.id===value);if(c)openModal(c.title,`<p class="creator-bio">${esc(c.summary)}</p><p class="terms">${esc(c.details)}</p>${c.evidence_url?`<a class="btn" href="${esc(c.evidence_url)}" target="_blank" rel="noopener noreferrer">Source reference ↗</a>`:''}`);return;}
 if(name==='about')return openModal('Independent minds. Shared ambition.',`<p class="creator-bio">We believe the best stories come from real connections.</p><p class="terms">Voqro brings brands, creators and the people behind the work into one thoughtful space. Our approach is simple: find the right people, make the brief clear, and give good ideas room to grow.</p><p class="fineprint">This agency profile is illustrative. No case studies or commercial outcomes are claimed in this demonstration.</p><div class="modal-footer">${btn('Tell us your story','enquire','primary','arrow')}</div>`);
 if(name==='search'){openModal('Find a little clarity.',`<div class="field-search">${icon('search')}<input id="global-search" placeholder="Search campaigns, creators, proposals…" aria-label="Search workspace"></div><div id="search-results" class="search-results detail-tags"><p class="source-note">Type a name, brand or campaign to begin.</p></div>`);return;}
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();Promise.resolve(action(el.dataset.action,el)).catch(err=>toast(err.message));}if(e.target.classList.contains('modal-backdrop'))closeModal();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();$('#sidebar')?.classList.remove('open');}if((e.metaKey||e.ctrlKey)&&e.key==='k'&&state){e.preventDefault();action('search');}if(e.key==='Enter'&&e.target.matches('[role=button]'))action(e.target.dataset.action);if(e.key==='Tab'&&$('.modal')){const controls=[...document.querySelectorAll('.modal button,.modal input:not([type=hidden]),.modal select,.modal textarea,.modal a')].filter(e=>!e.disabled);if(e.shiftKey&&document.activeElement===controls[0]){e.preventDefault();controls.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===controls.at(-1)){e.preventDefault();controls[0].focus();}}});
document.addEventListener('input',e=>{if(e.target.id==='creator-search'){search=e.target.value;const pos=e.target.selectionStart;render();$('#creator-search').focus();$('#creator-search').setSelectionRange(pos,pos);}if(e.target.closest('.line-item'))updateItems();if(e.target.id==='global-search'){const q=e.target.value.toLowerCase().trim();const results=[...state.campaigns.map(c=>({name:c.name,type:'Campaign',a:'campaign:'+c.id})),...state.creators.map(c=>({name:c.name,type:'Creator',a:'creator:'+c.id})),...state.proposals.map(p=>({name:p.title,type:'Proposal',a:'proposal:'+p.id}))].filter(r=>q&&r.name.toLowerCase().includes(q));$('#search-results').innerHTML=results.map(r=>`<button class="search-result" data-action="${r.a}">${esc(r.name)}<small>${r.type}</small></button>`).join('')||'<p class="source-note">'+(q?'No matches. Try another name.':'Type a name, brand or campaign to begin.')+'</p>';}});
document.addEventListener('change',e=>{if(e.target.id==='proposal-version')proposalModal(e.target.dataset.id,e.target.value);if(e.target.id==='shortlist-brand'){selectedBrand=e.target.value;render();}if(e.target.id==='add-creator'&&e.target.value){updateItems();const c=creator(e.target.value);composerItems.push({label:'Instagram Reel · '+c.name,quantity:1,unit_price:2500000,creator_id:c.id});$('#line-items').innerHTML=composerItems.map(lineItemHTML).join('');e.target.value='';updateItems();}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;if(form.id.startsWith('ntf-'))return emailPanel.submit(form);if(form.id.startsWith('identity-'))return accessPanel.submit(form);if(form.id.startsWith('opt-'))return opt.submit(form);if(form.id.startsWith('wf-'))return wf.submit(form);if(form.id.startsWith('report-'))return reports.submit(form);if(form.id.startsWith('cloud-'))return cloudPanel.submit(form);if(form.id.startsWith('ig-'))return ig.submit(form);if(form.id.startsWith('cat-'))return cat.submit(form);if(form.id.startsWith('cash-'))return cash.submit(form);if(form.id.startsWith('ops-'))return ops.submit(form);if(form.id.startsWith('delivery-'))return delivery.submit(form);const b=Object.fromEntries(new FormData(form)),submit=form.querySelector('[type=submit]');submit.disabled=true;form.querySelector('.form-error').textContent='';try{
 if(form.id==='enquiry-form'){b.budget=Math.round(Number(b.budget)*100);const result=await api('enquiries',b);if(state&&canSales())await refresh();openModal('A good beginning.',`<p class="creator-bio">Thanks, ${esc(b.name.split(' ')[0])}. Your idea has a home.</p><p class="terms">Your enquiry for ${esc(b.company)} has been saved to the agency pipeline. Reference: ${esc(result.id)}.</p><p class="fineprint">Email notifications are not connected. Your enquiry is stored locally for the team to review.</p><div class="modal-footer">${btn('Back to the good stuff','close','primary','arrow')}</div>`);}
 if(form.id==='lead-form'){await api('leads/update',{id:form.dataset.id,stage:b.stage});closeModal();await refresh();toast('Conversation updated.');}
 if(form.id==='proposal-form'){b.items=readItems();await api('proposals',b);closeModal();view='proposals';await refresh();toast('Proposal shared. A new version is saved.');}
 if(form.id==='accept-form'){const result=await api('proposals/accept',{id:form.dataset.id,version_id:form.dataset.version});closeModal();view='campaign:'+result.campaign_id;await refresh();toast(result.already_accepted?'This campaign is already in your workspace.':'It’s a go. Your campaign has been created.');}
 }catch(err){if(form.isConnected)form.querySelector('.form-error').textContent=err.message;else toast(err.message);}finally{submit.disabled=false;}});
async function init(){try{publicData=await api('public');try{state=await api('workspace');}catch(e){if(e.status!==401)throw e;}if(state&&location.hash==='#workspace')render();else{state=null;publicPage();}}catch(e){$('#app').innerHTML=`<div class="layout-error"><h1>A small pause in the work.</h1><p>${esc(e.message)} Check that the application server is running, then retry.</p><button class="btn primary" data-action="reload">Try again</button></div>`;}}
document.addEventListener('click',e=>{if(e.target.closest('[data-action=reload]'))init();});
const cat=catalogUI({api,esc,btn,tag,heading,openModal,closeModal,toast,state:()=>state,view:()=>view,render,refresh});
const moduleContext={api,esc,icon,tag,btn,heading,openModal,closeModal,toast,date,state:()=>state,view:()=>view,render};
const accessPanel=identityUI(moduleContext);
const emailPanel=notificationsUI(moduleContext);
const opt=optimizationUI(moduleContext);
const wf=workflowUI(moduleContext);
const reports=reportingUI(moduleContext);
const cloudPanel=cloudUI(moduleContext);
const ig=instagramUI(moduleContext);
const cash=commerceUI({api,esc,icon,tag,btn,heading,openModal,closeModal,toast,money,date,state:()=>state,view:()=>view,render});
const ops=operationsUI({api,esc,icon,tag,btn,heading,openModal,closeModal,toast,state:()=>state,view:()=>view,render});
const delivery=deliveryUI({cloudUpload:cloudPanel.uploadFile,api,esc,icon,tag,btn,date,openModal,closeModal,toast,state:()=>state,view:()=>view,render,refresh});
init();

matchMedia("(max-width: 700px)").addEventListener("change",event=>{if(event.matches){document.querySelector(".sidebar")?.classList.remove("open");if(document.activeElement?.closest(".sidebar"))document.querySelector(".mobile-menu")?.focus({preventScroll:true});}});
